167	    const term = `%${filters.search}%`;
168	    params.push(term, term, term, term);
169	  }
170	  if (filters?.opponent_id) {
171	    conditions.push('opponent_id = ?');
172	    params.push(filters.opponent_id);
173	  }
174	  if (filters?.week_id) {
175	    conditions.push('week_id = ?');
